B.ad3=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc758 \uacc4\ud68d\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc758 \uc77c\uc740 \ub0b4\uac00 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6b8 \ub54c\ub3c4 \uc788\uc5b4\uc694. \ub098\ub294 \uadf8 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \ud558\ub098\ub2d8\uc744 \ubbff\uace0 \uc788\ub098\uc694? \uc9c0\uae08 \ub0b4 \uc0b6 \uc18d\uc5d0\uc11c\ub3c4 \ud558\ub098\ub2d8\uc774 \uc77c\ud558\uace0 \uacc4\uc2ec\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.acK=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ub9d0\uc500\uc5d0 \uc21c\uc885\ud558\uace0 \uc788\ub098\uc694?","\ub9c8\ub9ac\uc544\ub294 \ubaa8\ub4e0 \uc0c1\ud669\uc744 \uc774\ud574\ud558\uc9c0 \ubabb\ud574\ub3c4 \uc21c\uc885\ud588\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uc54c\uba74\uc11c\ub3c4 \ubbf8\ub8e8\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc9c0\uae08 \uc21c\uc885\ud574\uc57c \ud560 \uac83\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.adk=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \ud5a5\ud55c \ubbff\uc74c\uc744 \uace0\ubc31\ud558\uace0 \uc788\ub098\uc694?","\ub9c8\uc74c\uc73c\ub85c\ub9cc \ubbff\ub294 \uac83\uc5d0 \uadf8\uce58\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uc774 \ud558\uc2e0 \uc77c\uc744 \uc778\uc815\ud558\uace0 \uace0\ubc31\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc5d0\uc11c \ubbff\uc74c\uc774 \ub4dc\ub7ec\ub098\uace0 \uc788\ub098\uc694?")
B.a1l=s([B.ad3,B.acK,B.adk],t.a)
B.XR=new A.b1("luke-lesson-1","path-luke","\ud558\ub098\ub2d8\uc758 \uacc4\ud68d\uacfc \uc57d\uc18d\uc758 \uc2dc\uc791","\ub204\uac00\ubcf5\uc74c 1\uc7a5","\ub204\uac00\ubcf5\uc74c\uc740 \uc608\uc218\ub2d8\uc758 \ud0c4\uc0dd \uc774\uc57c\uae30\ub97c \uc790\uc138\ud558\uac8c \uae30\ub85d\ud558\uba70 \uc2dc\uc791\ud574\uc694. \uc138\ub840 \uc694\ud55c\uc758 \ucd9c\uc0dd\uc774 \uba3c\uc800 \uc608\uace0\ub418\uace0, \uc774\uc5b4\uc11c \ucc9c\uc0ac\uac00 \ub9c8\ub9ac\uc544\uc5d0\uac8c \ub098\ud0c0\ub098 \uc608\uc218\ub2d8\uc758 \ud0c4\uc0dd\uc744 \uc54c\ub9ac\uc8e0. \ub9c8\ub9ac\uc544\ub294 \ub180\ub77c\uc6b4 \uc18c\uc2dd\uc744 \ub4e3\uace0\ub3c4 \ud558\ub098\ub2d8\uc758 \ub9d0\uc500\uc5d0 \uc21c\uc885\ud558\ub294 \ud0dc\ub3c4\ub97c \ubcf4\uc774\uc138\uc694. \ub610\ud55c \uc5d8\ub9ac\uc0ac\ubcb3\uacfc\uc758 \ub9cc\ub0a8 \uc18d\uc5d0\uc11c \ud558\ub098\ub2d8\uc758 \uc57d\uc18d\uc774 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\uc74c\uc744 \ud655\uc778\ud574\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc758 \uacc4\ud68d\uc774 \uc0ac\ub78c\uc744 \ud1b5\ud574 \uc870\uc6a9\ud788 \uadf8\ub7ec\ub098 \ud655\uc2e4\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \uacc4\ud68d\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?",B.a1l)
B.ae7=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc774 \ud558\uc2dc\ub294 \uc77c\uc744 \uc54c\uc544\ubcf4\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc740 \ud654\ub824\ud55c \uacf3\uc774 \uc544\ub2c8\ub77c \ub0ae\uc740 \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uc77c\ud558\uc138\uc694. \ub098\ub294 \uadf8 \uc77c\uc744 \ubcf4\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \ub193\uce58\uace0 \uc788\ub098\uc694?")
B.abm=new A.U("\ub098\ub294 \uae30\uc068\uc73c\ub85c \ud558\ub098\ub2d8\uc744 \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?","\ubaa9\uc790\ub4e4\uc740 \uae30\uc068\uc73c\ub85c \ubc18\uc751\ud588\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc774 \ud558\uc2e0 \uc77c\uc5d0 \ubb34\ub364\ub364\ud558\uc9c0 \uc54a\ub098\uc694? \uac10\uc0ac\uc640 \uae30\uc068\uc774 \uc788\ub098\uc694?")
B.adc=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \ub354 \uc54c\uc544\uac00\uace0 \uc788\ub098\uc694?","\uc608\uc218\ub2d8\ub3c4 \uc790\ub77c\uba70 \ud558\ub098\ub2d8\uc744 \uc54c\uc544\uac00\uc168\uc5b4\uc694. \ub098\ub294 \uc131\uc7a5\ud558\uace0 \uc788\ub098\uc694? \uba48\ucdb0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694?")
B.a0i=s([B.ae7,B.abm,B.adc],t.a)
B.Xr=new A.b1("luke-lesson-2","path-luke","\uc608\uc218\ub2d8\uc758 \ud0c4\uc0dd\uacfc \ud558\ub098\ub2d8\uc758 \uc778\ub3c4\ud558\uc2ec","\ub204\uac00\ubcf5\uc74c 2\uc7a5","\uc608\uc218\ub2d8\uc740 \ubca0\ub4e4\ub808\ud5f4\uc5d0\uc11c \ud0dc\uc5b4\ub098\uc2dc\uace0, \ucc9c\uc0ac\ub4e4\uc740 \ubaa9\uc790\ub4e4\uc5d0\uac8c \uadf8 \uc18c\uc2dd\uc744 \uc804\ud574\uc694. \ubaa9\uc790\ub4e4\uc740 \uc989\uc2dc \ucc3e\uc544\uac00 \uc544\uae30 \uc608\uc218\ub2d8\uc744 \uacbd\ubc30\ud558\uba70 \uae30\uc068\uc73c\ub85c \ub3cc\uc544\uac00\uc694. \uc2dc\ubbc0\uc628\uacfc \uc548\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ubcf4\uace0 \ud558\ub098\ub2d8\uc758 \uc57d\uc18d\uc774 \uc774\ub8e8\uc5b4\uc84c\uc74c\uc744 \uc54c\uc544\ubd10\uc694. \uc5b4\ub9b0 \uc608\uc218\ub2d8\uc740 \uc131\uc804\uc5d0\uc11c \ud558\ub098\ub2d8\uc744 \uc544\ub294 \uc9c0\ud61c\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc774 \ub0ae\uc740 \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uc77c\ud558\uc2dc\uba70 \uadf8\ubd84\uc744 \uc54c\uc544\ubcf4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc774 \ud558\uc2dc\ub294 \uc77c\uc744 \uc54c\uc544\ubcf4\uace0 \uc788\ub098\uc694?",B.a0i)
B.ad7=new A.U("\ub098\ub294 \uc9c4\uc9dc\ub85c \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694?","\ud68c\uac1c\ub294 \ub9d0\ub85c \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\uc5d0\uc694. \ub098\ub294 \ub0b4 \uc0b6\uc5d0\uc11c \ubc14\ub00c\uace0 \uc788\ub294 \ubd80\ubd84\uc774 \uc788\ub098\uc694? \ubc18\ubcf5\ub418\ub294 \ubaa8\uc2b5 \uadf8\ub300\ub85c \uba38\ubb3c\ub7ec \uc788\uc9c0\ub294 \uc54a\ub098\uc694?")
B.acr=new A.U("\ub098\ub294 \ub0b4 \uc0b6\uc744 \ub3cc\uc544\ubcf4\uace0 \uc788\ub098\uc694?","\ubc14\uc058\uac8c \uc0b4\ub2e4 \ubcf4\uba74 \uc790\uc2e0\uc744 \ub3cc\uc544\ubcf4\uc9c0 \ubabb\ud560 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ub0b4 \uc0c1\ud0dc\ub97c \uc810\uac80\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \ubaa8\uc2b5\uc778\uac00\uc694?")
B.ad0=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \uc55e\uc5d0 \uc900\ube44\ub41c \ub9c8\uc74c\uc73c\ub85c \uc11c \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc740 \uac89\uc774 \uc544\ub2c8\ub77c \uc911\uc2ec\uc744 \ubcf4\uc138\uc694. \ub098\ub294 \uc9c4\uc2ec\uc73c\ub85c \ud558\ub098\ub2d8\uc744 \ud5a5\ud558\uace0 \uc788\ub098\uc694? \uc900\ube44\ub41c \ub9c8\uc74c\uc778\uac00\uc694?")
B.a6b=s([B.ad7,B.acr,B.ad0],t.a)
B.XP=new A.b1("luke-lesson-3","path-luke","\ud68c\uac1c\uc640 \uc900\ube44\ub41c \ub9c8\uc74c","\ub204\uac00\ubcf5\uc74c 3\uc7a5","\uc138\ub840 \uc694\ud55c\uc740 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud68c\uac1c\ub97c \uc120\ud3ec\ud558\uba70 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \uc900\ube44\ud558\ub77c\uace0 \ub9d0\ud574\uc694. \ub2e8\uc21c\ud55c \ub9d0\uc774 \uc544\ub2c8\ub77c \uc0b6\uc758 \ubcc0\ud654, \uc989 \uc5f4\ub9e4 \ub9fa\ub294 \ud68c\uac1c\ub97c \uac15\uc870\ud574\uc694. \uc0ac\ub78c\ub4e4\uc740 \uc5b4\ub5bb\uac8c \uc0b4\uc544\uc57c \ud558\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ubb3b\uace0, \uc694\ud55c\uc740 \uc0b6 \uc18d\uc5d0\uc11c \uc2e4\ucc9c\ud560 \uac83\uc744 \uc54c\ub824\uc918\uc694. \uc774\ud6c4 \uc608\uc218\ub2d8\uc774 \uc138\ub840\ub97c \ubc1b\uc73c\uc2dc\uace0 \uc131\ub839\uc774 \uc784\ud558\uba70 \ud558\ub098\ub2d8\uc758 \uc74c\uc131\uc774 \ub4e4\ub824\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8 \uc55e\uc5d0 \ub098\uc544\uac00\uae30 \uc704\ud574\uc11c\ub294 \uc9c4\uc9dc \ubcc0\ud654\uac00 \ud544\uc694\ud568\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc9c4\uc9dc\ub85c \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694?",B.a6b)
B.acG=new A.U("\ub098\ub294 \uc720\ud639 \uc55e\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?","\uc720\ud639\uc740 \ud53c\ud560 \uc218 \uc5c6\uc5b4\uc694. \uc911\uc694\ud55c \uac83\uc740 \ub098\uc758 \ubc18\uc751\uc774\uc5d0\uc694. \ub098\ub294 \ub9d0\uc500\uc744 \uae30\uc900\uc73c\ub85c \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?")
B.abk=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc758 \ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?","\uc775\uc219\ud568 \ub54c\ubb38\uc5d0 \ubb34\uc2dc\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc5f4\ub9b0 \ub9c8\uc74c\uc73c\ub85c \ub4e3\uace0 \uc788\ub098\uc694? \uc0b6\uc5d0 \uc801\uc6a9\ud558\uace0 \uc788\ub098\uc694?")
B.adT=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc774 \uc8fc\uc2e0 \uc0ac\uba85\uc744 \uc54c\uace0 \uc788\ub098\uc694?","\uc608\uc218\ub2d8\uc740 \ubd84\uba85\ud55c \uc0ac\uba85\uc744 \uac00\uc9c0\uace0 \uacc4\uc168\uc5b4\uc694. \ub098\ub294 \ub0b4 \uc0b6\uc758 \ubc29\ud5a5\uc744 \uc54c\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc774 \uc6d0\ud558\uc2dc\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?")
B.a5j=s([B.acG,B.abk,B.adT],t.a)
B.XT=new A.b1("luke-lesson-4","path-luke","\uc2dc\ud5d8\uacfc \uc0ac\uba85\uc758 \uc2dc\uc791","\ub204\uac00\ubcf5\uc74c 4\uc7a5","\uc608\uc218\ub2d8\uc740 \uc131\ub839\uc5d0 \uc774\ub04c\ub824 \uad11\uc57c\uc5d0\uc11c \uc2dc\ud5d8\uc744 \ubc1b\uc73c\uc138\uc694. \ub9c8\uadc0\ub294 \uc5ec\ub7ec \ubc29\uc2dd\uc73c\ub85c \uc720\ud639\ud558\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \ub9d0\uc500\uc73c\ub85c \uc774\uae30\uc138\uc694. \uc774\ud6c4 \uc608\uc218\ub2d8\uc740 \uc0ac\uc5ed\uc744 \uc2dc\uc791\ud558\uc2dc\uba70 \uac00\ub09c\ud55c \uc790\uc5d0\uac8c \ubcf5\uc74c\uc744 \uc804\ud558\ub7ec \uc624\uc168\ub2e4\uace0 \uc120\uc5b8\ud558\uc138\uc694. \uadf8\ub7ec\ub098 \uace0\ud5a5 \uc0ac\ub78c\ub4e4\uc740 \uc608\uc218\ub2d8\uc744 \ubc1b\uc544\ub4e4\uc774\uc9c0 \ubabb\ud574\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uc758 \uc0ac\uba85\uacfc \uc0ac\ub78c\ub4e4\uc758 \ub2e4\uc591\ud55c \ubc18\uc751\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc720\ud639 \uc55e\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?",B.a5j)
B.aeb=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc740 \uc9c0\uae08\ub3c4 \ub098\ub97c \ubd80\ub974\uace0 \uacc4\uc138\uc694. \ub098\ub294 \uadf8 \ubd80\ub974\uc2ec\uc744 \ub4e3\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \ubbf8\ub8e8\uace0 \uc788\ub098\uc694?")
B.adp=new A.U("\ub098\ub294 \ub098\uc758 \ubd80\uc871\ud568\uc744 \uc778\uc815\ud558\uace0 \uc788\ub098\uc694?","\uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \uc2dc\uc791\uc774\uc5d0\uc694. \ub098\ub294 \uc194\uc9c1\ud558\uac8c \ub098\ub97c \ubcf4\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.abd=new A.U("\ub098\ub294 \uc21c\uc885\uc73c\ub85c \uc0b4\uc544\uac00\uace0 \uc788\ub098\uc694?","\uc544\ub294 \uac83\uacfc \ud589\ub3d9\uc740 \ub2ec\ub77c\uc694. \ub098\ub294 \uc2e4\uc81c\ub85c \ub530\ub974\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc5d0 \ubcc0\ud654\uac00 \uc788\ub098\uc694?")
B.a1d=s([B.aeb,B.adp,B.abd],t.a)
B.XH=new A.b1("luke-lesson-5","path-luke","\ubd80\ub974\uc2ec\uacfc \uc21c\uc885","\ub204\uac00\ubcf5\uc74c 5\uc7a5","\uc608\uc218\ub2d8\uc740 \uc5b4\ubd80\ub4e4\uc744 \ubd80\ub974\uc2dc\uace0 \uadf8\ub4e4\uc740 \ubaa8\ub4e0 \uac83\uc744 \ub0b4\ub824\ub193\uace0 \ub530\ub974\uc138\uc694. \ubca0\ub4dc\ub85c\ub294 \uc790\uc2e0\uc758 \ubd80\uc871\ud568\uc744 \uae68\ub2eb\uace0 \uc608\uc218\ub2d8 \uc55e\uc5d0 \uc5ce\ub4dc\ub824\uc694. \uc608\uc218\ub2d8\uc740 \ub098\ubcd1\ud658\uc790\ub97c \uace0\uce58\uc2dc\uace0 \uc8c4\uc778\uc744 \ubd80\ub974\uc138\uc694. \uc0ac\ub78c\ub4e4\uc740 \uc810\uc810 \uc608\uc218\ub2d8\uaed8 \ubab0\ub824\ub4e4\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubd80\ub974\uc2ec \uc55e\uc5d0\uc11c\uc758 \ubc18\uc751\uacfc \uc21c\uc885\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?",B.a1d)
B.abq=new A.U("\ub098\ub294 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uc0b4\uc544\uac00\uace0 \uc788\ub098\uc694?","\uc138\uc0c1\uacfc \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uae30\uc900\uc740 \ub2ec\ub77c\uc694. \ub098\ub294 \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \uae30\uc900\uc740 \uc5b4\ub514\uc5d0 \uc788\ub098\uc694?")
B.abx=new A.U("\ub098\ub294 \uc6d0\uc218\ub97c \uc0ac\ub791\ud558\ub824\uace0 \ud558\uace0 \uc788\ub098\uc694?","\uc26c\uc6b4 \uc0ac\ub78c\ub9cc \uc0ac\ub791\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub97c \ud798\ub4e4\uac8c \ud558\ub294 \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \ub300\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub791\ud558\uace0 \uc788\ub098\uc694?")
B.aen=new A.U("\ub098\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud310\ub2e8\ud558\uace0 \uc788\ub098\uc694?","\uc27d\uac8c \ud3c9\uac00\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ub098 \uc790\uc2e0\uc744 \uba3c\uc800 \ub3cc\uc544\ubcf4\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uacb8\uc190\ud55c\uac00\uc694?")
B.a3b=s([B.abq,B.abx,B.aen],t.a)
B.WR=new A.b1("luke-lesson-6","path-luke","\ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uae30\uc900\uacfc \uc0b6","\ub204\uac00\ubcf5\uc74c 6\uc7a5","\uc608\uc218\ub2d8\uc740 \uc548\uc2dd\uc77c\uc5d0 \ub300\ud574 \uac00\ub974\uce58\uc2dc\uba70 \ud615\uc2dd\ubcf4\ub2e4 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc5f4\ub450 \uc81c\uc790\ub97c \uc138\uc6b0\uc2dc\uace0 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uae30\uc900\uc744 \uac00\ub974\uce58\uc138\uc694. \ubcf5\uacfc \ud654\ub97c \ud1b5\ud574 \uc138\uc0c1\uacfc \ub2e4\ub978 \uae30\uc900\uc744 \ubcf4\uc5ec\uc8fc\uc2dc\uace0, \uc6d0\uc218\ub97c \uc0ac\ub791\ud558\ub77c\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \ube44\ud310\ud558\uc9c0 \ub9d0\uace0 \uc6a9\uc11c\ud558\uba70 \uc5f4\ub9e4\ub85c \uc0ac\ub78c\uc744 \uc54c \uc218 \uc788\ub2e4\uace0 \ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc0b6\uc774 \uc138\uc0c1\uc758 \uae30\uc900\uacfc \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uc0b4\uc544\uac00\uace0 \uc788\ub098\uc694?",B.a3b)
B.adX=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?","\ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4 \ubbff\uace0 \uc788\ub098\uc694? \uc870\uac74\uc774 \uc788\uc5b4\uc57c \ubbff\ub294 \uac83\uc740 \uc544\ub2cc\uac00\uc694? \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.abH=new A.U("\ub098\ub294 \uc0ac\ub791\uc744 \ud45c\ud604\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\ub9c8\uc74c\ub9cc\uc73c\ub85c \ub05d\ub098\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud589\ub3d9\uc73c\ub85c \uc0ac\ub791\uc744 \ub4dc\ub7ec\ub0b4\uace0 \uc788\ub098\uc694? \ub204\uad70\uac00\uc5d0\uac8c \ud45c\ud604\ud558\uace0 \uc788\ub098\uc694?")
B.ac4=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uc194\uc9c1\ud558\uac8c \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?","\uac10\uc815\uc744 \uc228\uae30\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc788\ub294 \uadf8\ub300\ub85c \ud558\ub098\ub2d8\uaed8 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694? \uc9c4\uc9dc \ub9c8\uc74c\uc744 \ub4dc\ub9ac\uace0 \uc788\ub098\uc694?")
B.a_o=s([B.adX,B.abH,B.ac4],t.a)
B.Xl=new A.b1("luke-lesson-7","path-luke","\ubbff\uc74c\uacfc \uc0ac\ub791\uc758 \ubc18\uc751","\ub204\uac00\ubcf5\uc74c 7\uc7a5","\ubc31\ubd80\uc7a5\uc740 \ub9d0\uc500\ub9cc\uc73c\ub85c\ub3c4 \uce58\uc720\ud558\uc2e4 \uac83\uc744 \ubbff\ub294 \ud070 \ubbff\uc74c\uc744 \ubcf4\uc5ec\uc918\uc694. \uc608\uc218\ub2d8\uc740 \uacfc\ubd80\uc758 \uc544\ub4e4\uc744 \uc0b4\ub9ac\uc2dc\uba70 \uae0d\ud73c\uc744 \ub098\ud0c0\ub0b4\uc138\uc694. \uc138\ub840 \uc694\ud55c\uc740 \uc758\ubb38\uc744 \uac00\uc9c0\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \uc0ac\uc5ed\uc73c\ub85c \ub2f5\ud558\uc138\uc694. \ud55c \uc5ec\uc778\uc740 \ub208\ubb3c\ub85c \uc608\uc218\ub2d8\uc758 \ubc1c\uc744 \uc53b\uc73c\uba70 \uc0ac\ub791\uc744 \ud45c\ud604\ud574\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \uc0ac\ub791\uc774 \uc5b4\ub5bb\uac8c \ub4dc\ub7ec\ub098\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?",B.a_o)
B.acm=new A.U("\ub098\ub294 \ub9d0\uc500\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?","\ub4e3\uace0 \uc78a\uc5b4\ubc84\ub9ac\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub0b4 \uc0b6\uc5d0 \ubcc0\ud654\uac00 \uc788\ub098\uc694? \uc5f4\ub9e4\uac00 \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.adj=new A.U("\ub098\ub294 \ub450\ub824\uc6c0\ubcf4\ub2e4 \ubbff\uc74c\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?","\uc0c1\ud669\uc774 \ub354 \ud06c\uac8c \ubcf4\uc774\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc744 \ubc14\ub77c\ubcf4\uace0 \uc788\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?")
B.ael=new A.U("\ub098\ub294 \ubbff\uc74c\uc744 \ud589\ub3d9\uc73c\ub85c \uc62e\uae30\uace0 \uc788\ub098\uc694?","\uc0dd\uac01\ub9cc \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc2e4\uc81c\ub85c \uc6c0\uc9c1\uc774\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.a68=s([B.acm,B.adj,B.ael],t.a)
B.Xf=new A.b1("luke-lesson-8","path-luke","\ub9d0\uc500\uacfc \ubbff\uc74c\uc758 \ubc18\uc751","\ub204\uac00\ubcf5\uc74c 8\uc7a5","\uc528 \ubfcc\ub9ac\ub294 \ube44\uc720\ub97c \ud1b5\ud574 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub530\ub77c \ub9d0\uc500\uc774 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \ud3ed\ud48d\uc744 \uc7a0\uc7a0\ud558\uac8c \ud558\uc2dc\uba70 \ubbff\uc74c\uc744 \uac00\ub974\uce58\uc2dc\uace0, \uadc0\uc2e0 \ub4e4\ub9b0 \uc0ac\ub78c\uc744 \uace0\uce58\uc138\uc694. \ub610\ud55c \ubcd1\ub4e0 \uc5ec\uc778\uacfc \uc8fd\uc740 \uc18c\ub140\ub97c \uc0b4\ub9ac\uc2dc\uba70 \ubbff\uc74c\uc758 \uc911\uc694\uc131\uc744 \uac15\uc870\ud558\uc138\uc694. \uc81c\uc790\ub4e4\uc740 \uc5ec\uc804\ud788 \ub450\ub824\uc6cc\ud574\uc694. \uc774 \uc7a5\uc740 \ub9d0\uc500\uacfc \ubbff\uc74c\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ub9d0\uc500\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?",B.a68)
B.abW=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub204\uad6c\ub77c\uace0 \uace0\ubc31\ud558\uace0 \uc788\ub098\uc694?","\ub2e8\uc21c\ud788 \uc544\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub098\uc758 \uace0\ubc31\uc774 \uc911\uc694\ud574\uc694. \ub098\ub294 \uc608\uc218\ub2d8\uc744 \uc5b4\ub5a4 \ubd84\uc73c\ub85c \ubbff\uace0 \uc788\ub098\uc694? \uadf8 \ubbff\uc74c\uc774 \ub0b4 \uc0b6\uc5d0 \ub4dc\ub7ec\ub098\uace0 \uc788\ub098\uc694?")
B.aea=new A.U("\ub098\ub294 \uc2ed\uc790\uac00\ub97c \uc9c0\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\ud3b8\ud55c \uae38\ub9cc \uc120\ud0dd\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc774 \uc6d0\ud558\uc2dc\ub294 \uae38\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694? \ub0b4\uac00 \ub0b4\ub824\ub193\uc544\uc57c \ud560 \uac83\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.adv=new A.U("\ub098\ub294 \ub05d\uae4c\uc9c0 \ub530\ub974\uace0 \uc788\ub098\uc694?","\uc2dc\uc791\uc740 \uc26c\uc6cc\ub3c4 \uacc4\uc18d \uac00\ub294 \uac83\uc740 \uc5b4\ub824\uc6cc\uc694. \ub098\ub294 \ud754\ub4e4\ub9ac\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc9c0\uae08\ub3c4 \ub530\ub77c\uac00\uace0 \uc788\ub098\uc694?")
B.a0s=s([B.abW,B.aea,B.adv],t.a)
B.Xg=new A.b1("luke-lesson-9","path-luke","\uc81c\uc790\uc758 \uae38\uacfc \ub530\ub984\uc758 \uc758\ubbf8","\ub204\uac00\ubcf5\uc74c 9\uc7a5","\uc608\uc218\ub2d8\uc740 \uc81c\uc790\ub4e4\uc744 \ubcf4\ub0b4\uc2dc\uba70 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \uc804\ud558\uac8c \ud558\uc138\uc694. \uc624\ubcd1\uc774\uc5b4 \uae30\uc801\uc744 \ud1b5\ud574 \ud558\ub098\ub2d8\uc758 \ub2a5\ub825\uc744 \ubcf4\uc5ec\uc8fc\uc2dc\uace0, \ubca0\ub4dc\ub85c\ub294 \uc608\uc218\ub2d8\uc744 \uadf8\ub9ac\uc2a4\ub3c4\ub85c \uace0\ubc31\ud574\uc694. \uc774\ud6c4 \uc608\uc218\ub2d8\uc740 \uc790\uc2e0\uc758 \uace0\ub09c\uacfc \uc8fd\uc74c\uc744 \uc608\uace0\ud558\uc2dc\uace0, \uc81c\uc790\ub294 \uc790\uae30 \uc2ed\uc790\uac00\ub97c \uc9c0\uace0 \ub530\ub77c\uc57c \ud55c\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ubcc0\ud654\uc0b0\uc5d0\uc11c \uc608\uc218\ub2d8\uc758 \uc601\uad11\uc774 \ub4dc\ub7ec\ub098\uace0 \ud558\ub098\ub2d8\uc758 \uc74c\uc131\uc774 \ub4e4\ub824\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub97c \ub530\ub978\ub2e4\ub294 \uac83\uc774 \uc5b4\ub5a4 \uc758\ubbf8\uc778\uc9c0 \ubd84\uba85\ud558\uac8c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub204\uad6c\ub77c\uace0 \uace0\ubc31\ud558\uace0 \uc788\ub098\uc694?",B.a0s)
B.abn=new A.U("\ub098\ub294 \uc9c4\uc9dc\ub85c \uc0ac\ub791\uc744 \uc2e4\ucc9c\ud558\uace0 \uc788\ub098\uc694?","\ub9d0\ub85c\ub9cc \uc0ac\ub791\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc2e4\uc81c\ub85c \ub204\uad70\uac00\ub97c \ub3d5\uace0 \uc788\ub098\uc694? \ud589\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.acD=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \uc6b0\uc120\ud558\uace0 \uc788\ub098\uc694?","\ubc14\uc058\ub2e4\ub294 \uc774\uc720\ub85c \ud558\ub098\ub2d8\uc744 \ub4a4\ub85c \ubbf8\ub8e8\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \uba3c\uc800 \ub450\uace0 \uc788\ub098\uc694? \ub0b4 \uc2dc\uac04\uc740 \uc5b4\ub514\uc5d0 \uc4f0\uc774\uace0 \uc788\ub098\uc694?")
B.acU=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \uc55e\uc5d0 \uba38\ubb34\ub294 \uc2dc\uac04\uc744 \uac00\uc9c0\uace0 \uc788\ub098\uc694?","\ub9c8\ub9ac\uc544\ub294 \uc608\uc218\ub2d8 \ubc1c \uc55e\uc5d0 \uba38\ubb3c\ub800\uc5b4\uc694. \ub098\ub294 \uba48\ucd94\uace0 \ud558\ub098\ub2d8\uacfc \uc2dc\uac04\uc744 \ubcf4\ub0b4\uace0 \uc788\ub098\uc694? \ubd84\uc8fc\ud568\uc774 \uadf8 \uc2dc\uac04\uc744 \ube7c\uc557\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694?")
B.a4R=s([B.abn,B.acD,B.acU],t.a)
B.XL=new A.b1("luke-lesson-10","path-luke","\uc0ac\ub791\uacfc \uc12c\uae40\uc758 \uc0b6","\ub204\uac00\ubcf5\uc74c 10\uc7a5","\uc608\uc218\ub2d8\uc740 70\uc778\uc744 \ubcf4\ub0b4\uc2dc\uba70 \ubcf5\uc74c\uc744 \uc804\ud558\uac8c \ud558\uc138\uc694. \uc0ac\uc5ed\uc744 \ud1b5\ud574 \uae30\uc068\uc744 \uacbd\ud5d8\ud558\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \ub354 \uc911\uc694\ud558\uac8c \ub9d0\uc500\ud558\uc138\uc694. \uc120\ud55c \uc0ac\ub9c8\ub9ac\uc544\uc778\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \uc9c4\uc9dc \uc774\uc6c3 \uc0ac\ub791\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubcf4\uc5ec\uc8fc\uc138\uc694. \ub610\ud55c \ub9c8\ub974\ub2e4\uc640 \ub9c8\ub9ac\uc544 \uc774\uc57c\uae30\ub97c \ud1b5\ud574 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\uac00 \uc6b0\uc120\uc784\uc744 \uac15\uc870\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uc0ac\ub791\uacfc \uc12c\uae40, \uadf8\ub9ac\uace0 \uc6b0\uc120\uc21c\uc704\ub97c \uac00\ub974\uccd0\uc694.","\ub098\ub294 \uc9c4\uc9dc\ub85c \uc0ac\ub791\uc744 \uc2e4\ucc9c\ud558\uace0 \uc788\ub098\uc694?",B.a4R)
B.ae3=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uacfc \ub300\ud654\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\uae30\ub3c4\uac00 \ud615\uc2dd\uc774 \ub418\uc5b4\ubc84\ub9ac\uc9c0\ub294 \uc54a\uc558\ub098\uc694? \ub098\ub294 \uc9c4\uc9dc\ub85c \ud558\ub098\ub2d8\uacfc \uc774\uc57c\uae30\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\uac00 \uc0b4\uc544 \uc788\ub098\uc694?")
B.ac1=new A.U("\ub098\ub294 \ub048\uae30 \uc788\uac8c \uae30\ub3c4\ud558\uace0 \uc788\ub098\uc694?","\uae30\ub3c4\ub97c \ud558\ub2e4 \uae08\ubc29 \ud3ec\uae30\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uacc4\uc18d\ud574\uc11c \uc8fc\ub2d8\uc758 \ub2f5\uc744 \uad6c\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.abT=new A.U("\ub098\ub294 \ub9c8\uc74c\uc774 \uae68\ub057\ud55c \uc0c1\ud0dc\uc778\uac00\uc694?","\uac89\uc740 \uad1c\ucc2e\uc544 \ubcf4\uc5ec\ub3c4 \uc18d\uc740 \ub2e4\ub97c \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ub0b4 \ub9c8\uc74c\uc744 \uc810\uac80\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc815\uc9c1\ud55c\uac00\uc694?")
B.ZN=s([B.ae3,B.ac1,B.abT],t.a)
B.X6=new A.b1("luke-lesson-11","path-luke","\uae30\ub3c4\uc640 \ub9c8\uc74c\uc758 \uc0c1\ud0dc","\ub204\uac00\ubcf5\uc74c 11\uc7a5","\uc608\uc218\ub2d8\uc740 \uc81c\uc790\ub4e4\uc5d0\uac8c \uae30\ub3c4\ub97c \uac00\ub974\uce58\uc2dc\uba70 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \uad6c\ud558\uace0 \ucc3e\uace0 \ub450\ub4dc\ub9ac\ub77c\uace0 \ub9d0\uc500\ud558\uc2dc\uba70 \ub048\uc9c8\uae34 \uae30\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uac15\uc870\ud558\uc138\uc694. \ub610\ud55c \uadc0\uc2e0\uc744 \ucad3\uc544\ub0b4\uc2dc\uba70 \ud558\ub098\ub2d8\uc758 \ub098\ub77c\uac00 \uc784\ud588\uc74c\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc678\uc2dd\ud558\ub294 \uc2e0\uc559\uc744 \ucc45\ub9dd\ud558\uc2dc\uba70 \ub9c8\uc74c\uc758 \uc0c1\ud0dc\ub97c \uac15\uc870\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uae30\ub3c4\uc640 \ub0b4\uba74\uc758 \uc911\uc694\uc131\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uacfc \ub300\ud654\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?",B.ZN)
B.acb=new A.U("\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \ub450\ub824\uc6cc\ud558\uace0 \uc788\ub098\uc694?","\uc0ac\ub78c\uc758 \uc2dc\uc120\uc774\ub098 \uc0c1\ud669\uc744 \ub354 \ub450\ub824\uc6cc\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uc744 \ub354 \uc758\uc2dd\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694? \ub0b4 \ub9c8\uc74c\uc744 \ubd99\uc7a1\uace0 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.acN=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\uc5fc\ub824\uac00 \ub9ce\uc544\uc9c0\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uc774 \ub3cc\ubcf4\uc2e0\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubbff\uace0 \uc788\ub098\uc694? \uadf8 \ubbff\uc74c\uc774 \ub0b4 \uc0b6\uc5d0 \ub4dc\ub7ec\ub098\uace0 \uc788\ub098\uc694?")
B.acY=new A.U("\ub098\ub294 \uc900\ube44\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\uc5b8\uc820\uac00 \uc900\ube44\ud558\ub824\uace0 \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc9c0\uae08 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uae68\uc5b4 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \ubc29\ud5a5\uc740 \uc5b4\ub514\ub97c \ud5a5\ud558\uace0 \uc788\ub098\uc694?")
B.a07=s([B.acb,B.acN,B.acY],t.a)
B.XG=new A.b1("luke-lesson-12","path-luke","\ub450\ub824\uc6c0\uc774 \uc544\ub2cc \ud558\ub098\ub2d8\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0b6","\ub204\uac00\ubcf5\uc74c 12\uc7a5","\uc608\uc218\ub2d8\uc740 \uc678\uc2dd\uacfc \uc704\uc120\uc744 \uacbd\uace0\ud558\uc2dc\uba70 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \ub4dc\ub7ec\ub0a0 \uac83\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc0ac\ub78c\uc744 \ub450\ub824\uc6cc\ud558\uc9c0 \ub9d0\uace0 \ud558\ub098\ub2d8\uc744 \ub450\ub824\uc6cc\ud558\ub77c\uace0 \uac00\ub974\uce58\uc138\uc694. \ub610\ud55c \uc7ac\ubb3c\uc5d0 \ub300\ud55c \ube44\uc720\ub97c \ud1b5\ud574 \uc695\uc2ec\uc758 \uc704\ud5d8\uc131\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc5fc\ub824\ud558\uc9c0 \ub9d0\uace0 \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\ub77c\uace0 \ub9d0\uc500\ud558\uc2dc\uba70 \uc900\ube44\ub41c \uc0b6\uc744 \uac15\uc870\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\ub77c\ubcf4\uba70 \uc0b4\uc544\uc57c \ud558\ub294\uc9c0\ub97c \uc54c\ub824\uc918\uc694.","\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \ub450\ub824\uc6cc\ud558\uace0 \uc788\ub098\uc694?",B.a07)
B.abD=new A.U("\ub098\ub294 \uc9c0\uae08 \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694?","\ud68c\uac1c\ub294 \ud55c \ubc88\uc774 \uc544\ub2c8\ub77c \uacc4\uc18d\ub418\ub294 \uacfc\uc815\uc774\uc5d0\uc694. \ub098\ub294 \uacc4\uc18d \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \uac19\uc740 \uc790\ub9ac\uc5d0 \uba38\ubb3c\ub7ec \uc788\ub098\uc694?")
B.ac5=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc774 \uc8fc\uc2e0 \uae30\ud68c\ub97c \uc0ac\uc6a9\ud558\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc740 \uae30\ub2e4\ub824\uc8fc\uc2dc\uc9c0\ub9cc \uc601\uc6d0\ud788 \ubbf8\ub8e8\uba74 \uc548 \ub3fc\uc694. \ub098\ub294 \uc9c0\uae08 \uae30\ud68c\ub97c \ubd99\uc7a1\uace0 \uc788\ub098\uc694? \ubcc0\ud654\ud558\ub824\uace0 \ub178\ub825\ud558\uace0 \uc788\ub098\uc694?")
B.acQ=new A.U("\ub098\ub294 \uc791\uc740 \ubbff\uc74c\uc744 \uc18c\uc911\ud788 \uc5ec\uae30\uace0 \uc788\ub098\uc694?","\uc791\uc740 \uc2dc\uc791\uc774 \ud06c\uac8c \uc790\ub784 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \uc791\ub2e4\uace0 \ubb34\uc2dc\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc774 \uc77c\ud558\uc2ec\uc744 \ubbff\uace0 \uc788\ub098\uc694?")
B.a0F=s([B.abD,B.ac5,B.acQ],t.a)
B.WV=new A.b1("luke-lesson-13","path-luke","\ud68c\uac1c\uc640 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc131\uc7a5","\ub204\uac00\ubcf5\uc74c 13\uc7a5","\uc608\uc218\ub2d8\uc740 \ud68c\uac1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uba78\ub9dd\ud560 \uc218\ubc16\uc5d0 \uc5c6\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc5f4\ub9e4 \ub9fa\uc9c0 \ubabb\ud558\ub294 \ubb34\ud654\uacfc\ub098\ubb34 \ube44\uc720\ub97c \ud1b5\ud574 \uae30\ud68c\ub97c \uc8fc\uc2dc\ub294 \ud558\ub098\ub2d8\uc758 \uc778\ub0b4\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \ub610\ud55c \uc548\uc2dd\uc77c\uc5d0 \ubcd1\ub4e0 \uc5ec\uc778\uc744 \uace0\uce58\uc2dc\uba70 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac83\uc774 \uc911\uc694\ud568\uc744 \ub4dc\ub7ec\ub0b4\uc138\uc694. \uaca8\uc790\uc528\uc640 \ub204\ub8e9\uc758 \ube44\uc720\ub85c \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \ud655\uc7a5\uc744 \uc124\uba85\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud68c\uac1c\uc640 \ubcc0\ud654, \uadf8\ub9ac\uace0 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc131\uc7a5\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc9c0\uae08 \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694?",B.a0F)
B.acF=new A.U("\ub098\ub294 \uacb8\uc190\ud55c \ud0dc\ub3c4\ub85c \uc0b4\uace0 \uc788\ub098\uc694?","\ub192\uc544\uc9c0\uace0 \uc2f6\uc5b4 \ud558\ub294 \ub9c8\uc74c\uc774 \ud06c\uc9c0 \uc54a\ub098\uc694? \ub098\ub294 \ub0ae\uc544\uc9c0\ub294 \uc120\ud0dd\uc744 \ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \ud0dc\ub3c4\uc778\uac00\uc694?")
B.abS=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \uc6b0\uc120\ud558\uace0 \uc788\ub098\uc694?","\ub2e4\ub978 \uac83\ub4e4 \ub54c\ubb38\uc5d0 \ud558\ub098\ub2d8\uc744 \ub4a4\ub85c \ubbf8\ub8e8\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \ub354 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \uc6b0\uc120\uc21c\uc704\ub294 \ubb34\uc5c7\uc778\uac00\uc694?")
B.acR=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub530\ub97c \uc900\ube44\uac00 \ub418\uc5b4 \uc788\ub098\uc694?","\ub530\ub974\ub294 \uac83\uc740 \ub9d0\uc774 \uc544\ub2c8\ub77c \uacb0\ub2e8\uc774\uc5d0\uc694. \ub098\ub294 \uc2e4\uc81c\ub85c \ub530\ub974\uace0 \uc788\ub098\uc694? \ud3ec\uae30\ud574\uc57c \ud560 \uac83\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.a21=s([B.acF,B.abS,B.acR],t.a)
B.Xn=new A.b1("luke-lesson-14","path-luke","\uacb8\uc190\uacfc \uc81c\uc790\uc758 \ub300\uac00","\ub204\uac00\ubcf5\uc74c 14\uc7a5","\uc608\uc218\ub2d8\uc740 \uc794\uce58 \uc790\ub9ac\uc5d0\uc11c \uacb8\uc190\ud568\uc744 \uac00\ub974\uce58\uc138\uc694. \ub0ae\uc740 \uc790\ub97c \ucd08\ub300\ud558\ub77c\uace0 \ud558\uc2dc\uba70 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uac00\uce58\uad00\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \ud070 \uc794\uce58 \ube44\uc720\ub97c \ud1b5\ud574 \ucd08\ub300\ub97c \uac70\uc808\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc2b5\uc744 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \uc608\uc218\ub2d8\uc744 \ub530\ub974\ub294 \uac83\uc740 \ube44\uc6a9\uc744 \uacc4\uc0b0\ud574\uc57c \ud560 \ub9cc\ud07c \uc9c4\uc9c0\ud55c \uacb0\uc815\uc774\ub77c\uace0 \uac00\ub974\uce58\uc138\uc694. \uc774 \uc7a5\uc740 \uacb8\uc190\uacfc \ud5cc\uc2e0\uc758 \uc911\uc694\uc131\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \uacb8\uc190\ud55c \ud0dc\ub3c4\ub85c \uc0b4\uace0 \uc788\ub098\uc694?",B.a21)
B.ac_=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \ub3cc\uc544\uac00\uace0 \uc788\ub098\uc694?","\uba40\uc5b4\uc838 \uc788\uc73c\uba74\uc11c\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uaed8 \ub2e4\uc2dc \ub098\uc544\uac00\uace0 \uc788\ub098\uc694? \uc9c0\uae08 \ub0b4 \ub9c8\uc74c\uc758 \ubc29\ud5a5\uc740 \uc5b4\ub514\ub97c \ud5a5\ud558\uace0 \uc788\ub098\uc694?")
B.aef=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc758 \uc0ac\ub791\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?","\uc774\ubbf8 \uc0ac\ub791\ubc1b\uace0 \uc788\ub294\ub370\ub3c4 \uc2a4\uc2a4\ub85c \uac70\ubd80\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uadf8 \uc0ac\ub791\uc744 \ubbff\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc5d0\uc11c \uadf8\uac83\uc744 \ub204\ub9ac\uace0 \uc788\ub098\uc694?")
B.ac0=new A.U("\ub098\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud310\ub2e8\ud558\uace0 \uc788\ub098\uc694?","\ud070\uc544\ub4e4\ucc98\ub7fc \uac89\uc73c\ub85c\ub294 \uad1c\ucc2e\uc544 \ubcf4\uc5ec\ub3c4 \ub9c8\uc74c\uc740 \ub2e4\ub97c \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ube44\uad50\ud558\uace0 \ud310\ub2e8\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc758 \ub9c8\uc74c\uc73c\ub85c \ubc14\ub77c\ubcf4\uace0 \uc788\ub098\uc694?")
B.a0a=s([B.ac_,B.aef,B.ac0],t.a)
B.X2=new A.b1("luke-lesson-15","path-luke","\uc783\uc740 \uc790\ub97c \ucc3e\uc73c\uc2dc\ub294 \ud558\ub098\ub2d8","\ub204\uac00\ubcf5\uc74c 15\uc7a5","\uc608\uc218\ub2d8\uc740 \uc783\uc740 \uc591, \uc783\uc740 \ub4dc\ub77c\ud06c\ub9c8, \ub3cc\uc544\uc628 \uc544\ub4e4\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ud558\ub098\ub2d8\uc758 \ub9c8\uc74c\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \ud558\ub098\ub2d8\uc740 \ud55c \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc783\uc5b4\ubc84\ub9ac\uc9c0 \uc54a\uc73c\uc2dc\uace0 \ub05d\uae4c\uc9c0 \ucc3e\uc73c\uc138\uc694. \ud2b9\ud788 \ub3cc\uc544\uc628 \uc544\ub4e4\uc744 \uae30\uc068\uc73c\ub85c \ub9de\uc774\ud558\ub294 \uc544\ubc84\uc9c0\uc758 \ubaa8\uc2b5\uc5d0\uc11c \ud558\ub098\ub2d8\uc758 \uc0ac\ub791\uc774 \ub4dc\ub7ec\ub098\uc694. \ubc18\uba74 \ud070\uc544\ub4e4\uc740 \ub9c8\uc74c\uc73c\ub85c\ub294 \uc544\ubc84\uc9c0\uc640 \uba40\uc5b4\uc838 \uc788\uc5c8\uc5b4\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc774 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \uc6b0\ub9ac\ub97c \ubc14\ub77c\ubcf4\uc2dc\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \ub3cc\uc544\uac00\uace0 \uc788\ub098\uc694?",B.a0a)
B.adE=new A.U("\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?","\ub3c8\uacfc \uc131\uacf5\uc774 \uae30\uc900\uc774 \ub418\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \uc911\uc2ec\uc73c\ub85c \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \ubc29\ud5a5\uc740 \uc5b4\ub514\ub97c \ud5a5\ud558\uace0 \uc788\ub098\uc694?")
B.ae0=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc6b0\uc120\uc73c\ub85c \ub450\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uacfc \ub2e4\ub978 \uac83\uc744 \ub3d9\uc2dc\uc5d0 \ubd99\uc7a1\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \ub354 \uc0ac\ub791\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc120\ud0dd\uc5d0\uc11c \ub4dc\ub7ec\ub098\uace0 \uc788\ub098\uc694?")
B.adU=new A.U("\ub098\ub294 \uc601\uc6d0\uc744 \uc0dd\uac01\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\uc9c0\uae08\uc758 \uc0b6\uc774 \uc804\ubd80\ub77c\uace0 \uc0dd\uac01\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c\uc758 \uc0b6\uc744 \uc0dd\uac01\ud558\uace0 \uc788\ub098\uc694? \uc624\ub298\uc758 \uc120\ud0dd\uc774 \uc5b4\ub5a4 \uc758\ubbf8\ub97c \uac00\uc9c0\ub098\uc694?")
B.a27=s([B.adE,B.ae0,B.adU],t.a)
B.XA=new A.b1("luke-lesson-16","path-luke","\uc7ac\ubb3c\uacfc \uc601\uc6d0\ud55c \uac00\uce58","\ub204\uac00\ubcf5\uc74c 16\uc7a5","\uc608\uc218\ub2d8\uc740 \ubd88\uc758\ud55c \uccad\uc9c0\uae30\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \uc9c0\ud61c\ub86d\uac8c \uc0b4\uc544\uc57c \ud568\uc744 \uac00\ub974\uce58\uc138\uc694. \uc7ac\ubb3c\uc740 \uc601\uc6d0\ud558\uc9c0 \uc54a\uc73c\uba70 \ud558\ub098\ub2d8\uacfc \uc7ac\ubb3c\uc744 \ub3d9\uc2dc\uc5d0 \uc12c\uae38 \uc218 \uc5c6\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \ubd80\uc790\uc640 \ub098\uc0ac\ub85c\uc758 \uc774\uc57c\uae30\ub97c \ud1b5\ud574 \uc774 \ub545\uc758 \uc0b6\uc774 \ub05d\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc9c0\uae08\uc758 \uc120\ud0dd\uc774 \uc601\uc6d0\uacfc \uc5f0\uacb0\ub3fc \uc788\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \uc0b4\uc544\uc57c \ud558\ub294\uc9c0\ub97c \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud574\uc694.","\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?",B.a27)
B.adR=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uac10\uc0ac\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\ubc1b\uc740 \uac83\uc5d0 \uc775\uc219\ud574\uc838\uc11c \uac10\uc0ac\ud558\uc9c0 \uc54a\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uac10\uc0ac\uc758 \ud45c\ud604\uc744 \ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uaed8 \ub3cc\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.acq=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \uc778\uc2dd\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\ub208\uc5d0 \ubcf4\uc774\ub294 \uac83\ub9cc \ubbff\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc774 \uc774\ubbf8 \uc77c\ud558\uace0 \uacc4\uc2ec\uc744 \ubcf4\uace0 \uc788\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \ubc14\ub77c\ubcf4\uace0 \uc788\ub098\uc694?")
B.ac8=new A.U("\ub098\ub294 \uc900\ube44\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\uac11\uc791\uc2a4\ub7ec\uc6b4 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud56d\uc0c1 \uc900\ube44\ub418\uc5b4 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uae68\uc5b4 \uc788\ub098\uc694?")
B.a1D=s([B.adR,B.acq,B.ac8],t.a)
B.Xj=new A.b1("luke-lesson-17","path-luke","\uac10\uc0ac\uc640 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc778\uc2dd","\ub204\uac00\ubcf5\uc74c 17\uc7a5","\uc608\uc218\ub2d8\uc740 \uc6a9\uc11c\uc640 \ubbff\uc74c\uc758 \uc911\uc694\uc131\uc744 \uac00\ub974\uce58\uc138\uc694. \uc5f4 \uba85\uc758 \ub098\ubcd1\ud658\uc790\uac00 \uace0\uce68\uc744 \ubc1b\uc9c0\ub9cc \uc624\uc9c1 \ud55c \uc0ac\ub78c\ub9cc \ub3cc\uc544\uc640 \uac10\uc0ac\ud574\uc694. \ud558\ub098\ub2d8 \ub098\ub77c\ub294 \ub208\uc5d0 \ubcf4\uc774\ub294 \ubc29\uc2dd\uc774 \uc544\ub2c8\ub77c \uc774\ubbf8 \uc784\ud574 \uc788\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \ub9c8\uc9c0\ub9c9 \ub54c\uc758 \ubaa8\uc2b5\uc744 \uc124\uba85\ud558\uc2dc\uba70 \uc900\ube44\ub41c \uc0b6\uc744 \uac15\uc870\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uac10\uc0ac\uc640 \uc601\uc801\uc778 \uc2dc\uc120\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uac10\uc0ac\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?",B.a1D)
B.abI=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uacc4\uc18d \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?","\uae30\ub3c4\ub97c \uc27d\uac8c \ud3ec\uae30\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uafb8\uc900\ud788 \ud558\ub098\ub2d8\uaed8 \uad6c\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uba70 \uae30\ub2e4\ub9ac\uace0 \uc788\ub098\uc694?")
B.aei=new A.U("\ub098\ub294 \uacb8\uc190\ud55c \ub9c8\uc74c\uc73c\ub85c \ud558\ub098\ub2d8\uaed8 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?","\uc2a4\uc2a4\ub85c \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \ubaa8\uc2b5\uc778\uac00\uc694? \uc9c4\uc9dc\ub85c \ub0ae\uc544\uc838 \uc788\ub098\uc694?")
B.abE=new A.U("\ub098\ub294 \ub0b4\ub824\ub193\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \ubd99\uc7a1\uace0 \uc788\ub294 \uac83\uc774 \uc788\uc744 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ubb34\uc5c7\uc744 \ub193\uc9c0 \ubabb\ud558\uace0 \uc788\ub098\uc694? \uadf8\uac83\uc774 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \ub9c9\uace0 \uc788\uc9c0 \uc54a\ub098\uc694?")
B.a6a=s([B.abI,B.aei,B.abE],t.a)
B.XC=new A.b1("luke-lesson-18","path-luke","\uacb8\uc190\uacfc \ub048\uae30 \uc788\ub294 \ubbff\uc74c","\ub204\uac00\ubcf5\uc74c 18\uc7a5","\uc608\uc218\ub2d8\uc740 \ub048\uc9c8\uae30\uac8c \uad6c\ud558\ub294 \uacfc\ubd80\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \uae30\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uac00\ub974\uce58\uc138\uc694. \ubc14\ub9ac\uc0c8\uc778\uacfc \uc138\ub9ac\uc758 \uae30\ub3c4\ub97c \ud1b5\ud574 \uacb8\uc190\ud55c \ud0dc\ub3c4\uac00 \ud558\ub098\ub2d8\uaed8 \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc5b4\ub9b0\uc544\uc774\uc640 \uac19\uc740 \uc790\uac00 \ud558\ub098\ub2d8 \ub098\ub77c\uc5d0 \ud569\ub2f9\ud558\ub2e4\uace0 \ud558\uc138\uc694. \ubd80\uc790 \uad00\uc6d0\uc740 \uc7ac\ubb3c\uc744 \ub0b4\ub824\ub193\uc9c0 \ubabb\ud558\uace0 \ub5a0\ub098\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c\uc758 \ud0dc\ub3c4\uac00 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c\uc9c0\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uacc4\uc18d \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?",B.a6a)
B.aej=new A.U("\ub098\ub294 \ubcc0\ud654\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\uc608\uc218\ub2d8\uc744 \ub9cc\ub0ac\ub2e4\uba74 \ubcc0\ud654\uac00 \uc788\uc5b4\uc57c \ud574\uc694. \ub098\ub294 \uc774\uc804\uacfc \ub2ec\ub77c\uc84c\ub098\uc694? \ub0b4 \uc0b6\uc5d0\uc11c \uc5b4\ub5a4 \ubcc0\ud654\uac00 \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.abC=new A.U("\ub098\ub294 \ub9e1\uaca8\uc9c4 \uac83\uc744 \uc798 \uc0ac\uc6a9\ud558\uace0 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc740 \uac01\uc790\uc5d0\uac8c \ub9e1\uae30\uc2e0 \uac83\uc774 \uc788\uc5b4\uc694. \ub098\ub294 \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \uadf8\ub300\ub85c \ub450\uace0 \uc788\ub098\uc694?")
B.aby=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub0b4 \uc0b6\uc758 \uc655\uc73c\ub85c \uc778\uc815\ud558\uace0 \uc788\ub098\uc694?","\ub9d0\ub85c\ub9cc \uc778\uc815\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc2e4\uc81c\ub85c \uadf8\ubd84\uc758 \ub73b\uc744 \ub530\ub974\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \uc911\uc2ec\uc740 \ub204\uad6c\uc778\uac00\uc694?")
B.a13=s([B.aej,B.abC,B.aby],t.a)
B.XQ=new A.b1("luke-lesson-19","path-luke","\ud68c\uac1c\uc640 \ucc45\uc784, \uadf8\ub9ac\uace0 \uc655 \ub418\uc2e0 \uc608\uc218\ub2d8","\ub204\uac00\ubcf5\uc74c 19\uc7a5","\uc0ad\uac1c\uc624\ub294 \uc608\uc218\ub2d8\uc744 \ub9cc\ub098 \uc0b6\uc774 \uc644\uc804\ud788 \ubcc0\ud654\ub3fc\uc694. \uc608\uc218\ub2d8\uc740 \uc783\uc740 \uc790\ub97c \ucc3e\uc544 \uad6c\uc6d0\ud558\ub7ec \uc624\uc168\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ubbc0\ub098 \ube44\uc720\ub97c \ud1b5\ud574 \ub9e1\uaca8\uc9c4 \uac83\uc5d0 \ub300\ud55c \ucc45\uc784\uc744 \uac15\uc870\ud558\uc138\uc694. \uc608\uc218\ub2d8\uc740 \uc608\ub8e8\uc0b4\ub818\uc5d0 \uc655\uc73c\ub85c \uc785\uc131\ud558\uc2dc\uace0 \uc131\uc804\uc744 \uc815\uacb0\ud558\uac8c \ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ubcc0\ud654\ub41c \uc0b6\uacfc \ucc45\uc784 \uc788\ub294 \uc2e0\uc559\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ubcc0\ud654\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?",B.a13)
B.adF=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc758 \uad8c\uc704\ub97c \uc778\uc815\ud558\uace0 \uc788\ub098\uc694?","\ub0b4 \uc0dd\uac01\uc774 \ub354 \uc55e\uc11c\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uc744 \uae30\uc900\uc73c\ub85c \uc0b4\uace0 \uc788\ub098\uc694? \ub0b4 \uc120\ud0dd\uc740 \ubb34\uc5c7\uc744 \ub530\ub974\uace0 \uc788\ub098\uc694?")
B.acM=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?","\ubd88\ud3b8\ud55c \ub9d0\uc500\uc740 \ud53c\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ub4e3\uace0 \uc21c\uc885\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc5d0 \uc801\uc6a9\ud558\uace0 \uc788\ub098\uc694?")
B.acz=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc2dc\ud5d8\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694?","\uc870\uac74\uc744 \ubd99\uc774\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694? \uc9c4\uc9dc\ub85c \ub9e1\uae30\uace0 \uc788\ub098\uc694?")
B.a15=s([B.adF,B.acM,B.acz],t.a)
B.Xv=new A.b1("luke-lesson-20","path-luke","\uad8c\uc704\uc5d0 \ub300\ud55c \ud0dc\ub3c4","\ub204\uac00\ubcf5\uc74c 20\uc7a5","\uc885\uad50 \uc9c0\ub3c4\uc790\ub4e4\uc740 \uc608\uc218\ub2d8\uc758 \uad8c\uc704\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uc73c\ub824 \ud574\uc694. \ud3ec\ub3c4\uc6d0 \ub18d\ubd80 \ube44\uc720\ub97c \ud1b5\ud574 \ud558\ub098\ub2d8\uc744 \uac70\ubd80\ud558\ub294 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\uc138\uc694. \uc0ac\ub78c\ub4e4\uc740 \uc9c8\ubb38\uc73c\ub85c \uc608\uc218\ub2d8\uc744 \uc2dc\ud5d8\ud558\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \uc9c0\ud61c\ub86d\uac8c \ub2f5\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc758 \uad8c\uc704\ub97c \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc774\ub294\uc9c0\uac00 \uc911\uc694\ud568\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \uad8c\uc704\ub97c \uc778\uc815\ud558\uace0 \uc788\ub098\uc694?",B.a15)
B.adu=new A.U("\ub098\ub294 \uc9c4\uc2ec\uc73c\ub85c \ud558\ub098\ub2d8\uaed8 \ub4dc\ub9ac\uace0 \uc788\ub098\uc694?","\uc591\ubcf4\ub2e4 \ub9c8\uc74c\uc774 \uc911\uc694\ud574\uc694. \ub098\ub294 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ub4dc\ub9ac\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \ud5a5\ud55c \uc911\uc2ec\uc774 \uc788\ub098\uc694?")
B.abf=new A.U("\ub098\ub294 \uc900\ube44\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\ub098\uc911\uc5d0 \ud558\ub824\uace0 \ubbf8\ub8e8\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc9c0\uae08 \uc900\ube44\ub418\uc5b4 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uae68\uc5b4 \uc788\ub098\uc694?")
B.aeq=new A.U("\ub098\ub294 \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c\ub3c4 \ubbff\uc74c\uc744 \uc9c0\ud0a4\uace0 \uc788\ub098\uc694?","\uc0c1\ud669\uc774 \ud754\ub4e4\ub9b4 \ub54c \ubbff\uc74c\uc774 \ub4dc\ub7ec\ub098\uc694. \ub098\ub294 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \ubd99\uc7a1\uace0 \uc788\ub098\uc694?")
B.a3e=s([B.adu,B.abf,B.aeq],t.a)
B.XK=new A.b1("luke-lesson-21","path-luke","\ud5cc\uc2e0\uacfc \uc900\ube44\ub41c \uc0b6","\ub204\uac00\ubcf5\uc74c 21\uc7a5","\ud55c \uacfc\ubd80\uc758 \ud5cc\uae08\uc744 \ud1b5\ud574 \uc9c4\uc9dc \ud5cc\uc2e0\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc608\uc218\ub2d8\uc740 \ub9c8\uc9c0\ub9c9 \ub54c\uc758 \uc9d5\uc870\ub97c \ub9d0\uc500\ud558\uc2dc\uba70 \uc900\ube44\ub41c \uc0b6\uc744 \uac15\uc870\ud558\uc138\uc694. \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c\ub3c4 \ubbff\uc74c\uc744 \uc9c0\ucf1c\uc57c \ud55c\ub2e4\uace0 \ud558\uc138\uc694. \ud558\ub098\ub2d8\uc740 \ub05d\uae4c\uc9c0 \ud568\uaed8\ud558\uc2e0\ub2e4\uace0 \uc57d\uc18d\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud604\uc7ac\ub97c \uc5b4\ub5bb\uac8c \uc0b4\uc544\uc57c \ud558\ub294\uc9c0\ub97c \uc54c\ub824\uc918\uc694.","\ub098\ub294 \uc9c4\uc2ec\uc73c\ub85c \ud558\ub098\ub2d8\uaed8 \ub4dc\ub9ac\uace0 \uc788\ub098\uc694?",B.a3e)
B.adI=new A.U("\ub098\ub294 \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c\ub3c4 \ud558\ub098\ub2d8\uc744 \ub530\ub974\uace0 \uc788\ub098\uc694?","\ud798\ub4e4 \ub54c \ubbff\uc74c\uc774 \ud754\ub4e4\ub9b4 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \ubd99\uc7a1\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \ud3ec\uae30\ud558\uace0 \uc788\ub098\uc694?")
B.abZ=new A.U("\ub098\ub294 \ub0b4 \uc5f0\uc57d\ud568\uc744 \uc778\uc815\ud558\uace0 \uc788\ub098\uc694?","\uc2a4\uc2a4\ub85c \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \ub0b4 \ubaa8\uc2b5\uc744 \uc778\uc815\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uaed8 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?")
