B.X0=new A.b1("mark-lesson-1","path-mark","\ubcf5\uc74c\uc758 \uc2dc\uc791\uacfc \uc989\uac01\uc801\uc778 \uc21c\uc885","\ub9c8\uac00\ubcf5\uc74c 1\uc7a5","\ub9c8\uac00\ubcf5\uc74c\uc740 \uc608\uc218\ub2d8\uc758 \uc0ac\uc5ed\uc744 \ube60\ub974\uac8c \ubcf4\uc5ec\uc8fc\uba70 \ubcf5\uc74c\uc758 \uc2dc\uc791\uc744 \uc120\uc5b8\ud574\uc694. \uc138\ub840 \uc694\ud55c\uc740 \ud68c\uac1c\uc758 \uba54\uc2dc\uc9c0\ub97c \uc804\ud558\uba70 \uc608\uc218\ub2d8\uc758 \uae38\uc744 \uc900\ube44\ud574\uc694. \uc608\uc218\ub2d8\uc740 \uc138\ub840\ub97c \ubc1b\uc73c\uc2dc\uace0 \uace7\ubc14\ub85c \uc2dc\ud5d8\uc744 \uc774\uae30\uc2e0 \ud6c4 \uc0ac\uc5ed\uc744 \uc2dc\uc791\ud558\uc138\uc694. \uc81c\uc790\ub4e4\uc744 \ubd80\ub974\uc2e4 \ub54c \uadf8\ub4e4\uc740 \uc989\uc2dc \ubaa8\ub4e0 \uac83\uc744 \ubc84\ub9ac\uace0 \ub530\ub790\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubcf5\uc74c\uc774 \uc2dc\uc791\ub420 \ub54c \ub098\ud0c0\ub098\ub294 \uc989\uac01\uc801\uc778 \ubc18\uc751\uacfc \uc21c\uc885\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc989\uc2dc \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?",B.Ye)
B.adN=new A.U("\ub098\ub294 \ub0b4 \uc8c4\uc758 \uc0ac\ud568\uc744 \uc608\uc218\ub2d8\uaed8 \ub9e1\uae30\uace0 \uc788\ub098\uc694?","\uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \ubb38\uc81c\ubcf4\ub2e4 \ub9c8\uc74c\uc758 \uc0c1\ud0dc\uac00 \ub354 \uc911\uc694\ud574\uc694. \ub098\ub294 \ub0b4 \uc548\uc758 \uc798\ubabb\uacfc \ubd80\uc871\ud568\uc744 \uc194\uc9c1\ud558\uac8c \uc778\uc815\ud558\uace0 \uc788\ub098\uc694? \uadf8\uac83\uc744 \ud558\ub098\ub2d8\uaed8 \ub9e1\uae30\uace0 \ubcc0\ud654\ud558\ub824\uace0 \ud558\uace0 \uc788\ub098\uc694?")
B.adz=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc751\ub2f5\ud558\uace0 \uc788\ub098\uc694?","\ub808\uc704\ub294 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc989\uc2dc \ub530\ub790\uc5b4\uc694. \ub098\ub294 \ubd80\ub974\uc2ec \uc55e\uc5d0\uc11c \ub9dd\uc124\uc774\uace0 \uc788\ub098\uc694? \ubb34\uc5c7\uc774 \ub098\ub97c \ubd99\uc7a1\uace0 \uc788\ub098\uc694?")
B.abY=new A.U("\ub098\ub294 \ud615\uc2dd\ubcf4\ub2e4 \ubcf8\uc9c8\uc744 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?","\uc775\uc219\ud55c \ubc29\uc2dd\uc774 \uae30\uc900\uc774 \ub420 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\ubcf4\ub2e4 \uaddc\uce59\uc744 \ub354 \uc55e\uc138\uc6b0\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ubcf8\uc9c8\uc744 \ubcf4\uace0 \uc788\ub098\uc694?")
B.a73=s([B.adN,B.adz,B.abY],t.a)
B.X1=new A.b1("mark-lesson-2","path-mark","\uc8c4\ub97c \uc6a9\uc11c\ud558\uc2dc\ub294 \uc608\uc218\ub2d8\uacfc \uc0c8\ub85c\uc6b4 \uae30\uc900","\ub9c8\uac00\ubcf5\uc74c 2\uc7a5","\uc608\uc218\ub2d8\uc740 \uc911\ud48d\ubcd1\uc790\uc758 \uc8c4\ub97c \uba3c\uc800 \uc0ac\ud558\uc2dc\uba70 \uc601\uc801 \uad8c\uc704\ub97c \ub4dc\ub7ec\ub0b4\uc138\uc694. \uc0ac\ub78c\ub4e4\uc740 \ubcd1\uc758 \uce58\uc720\ub97c \uae30\ub300\ud588\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \ub354 \uadfc\ubcf8\uc801\uc778 \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc168\uc5b4\uc694. \uc138\ub9ac \ub808\uc704\ub97c \ubd80\ub974\uc2dc\uba70 \uc8c4\uc778\ub3c4 \ubd80\ub974\uc2dc\ub294 \uc740\ud61c\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \uae08\uc2dd\uacfc \uc548\uc2dd\uc77c\uc5d0 \ub300\ud55c \uac00\ub974\uce68\uc744 \ud1b5\ud574 \uc0c8\ub85c\uc6b4 \uc2dc\ub300\ub97c \uc120\ud3ec\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uc774 \uae30\uc874\uc758 \uc885\uad50\uc801 \ud2c0\uc744 \ub118\uc5b4 \uc0c8\ub85c\uc6b4 \uae30\uc900\uc744 \uc138\uc6b0\uc2dc\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ub0b4 \uc8c4\uc758 \uc0ac\ud568\uc744 \uc608\uc218\ub2d8\uaed8 \ub9e1\uae30\uace0 \uc788\ub098\uc694?",B.a73)
B.adW=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uc911\uc2ec\uc73c\ub85c \uc0b4\uace0 \uc788\ub098\uc694?","\uad00\uacc4\uc640 \uc0c1\ud669\uc774 \uae30\uc900\uc774 \ub420 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc911\uc2ec\uc5d0 \ub450\uace0 \uc788\ub098\uc694? \ub0b4 \uc120\ud0dd\uc758 \uae30\uc900\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.adD=new A.U("\ub098\ub294 \uc0ac\ub78c\ubcf4\ub2e4 \ud558\ub098\ub2d8\uc744 \ub354 \ub530\ub974\uace0 \uc788\ub098\uc694?","\uc8fc\ubcc0\uc758 \uc2dc\uc120\uc774 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \ub354 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694? \ub204\uad6c\uc758 \uae30\uc900\uc744 \ub530\ub974\uace0 \uc788\ub098\uc694?")
B.ada=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc758 \uacf5\ub3d9\uccb4 \uc548\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc778\uac00\uc694?","\uc9c4\uc9dc \uac00\uc871\uc740 \ubbff\uc74c\uc73c\ub85c \uc5f0\uacb0\ub3fc\uc694. \ub098\ub294 \uadf8 \uacf5\ub3d9\uccb4 \uc548\uc5d0 \uc788\ub098\uc694? \uadf8 \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.a3D=s([B.adW,B.adD,B.ada],t.a)
B.Xi=new A.b1("mark-lesson-3","path-mark","\uc608\uc218\ub2d8\uc758 \uad8c\uc704\uc640 \ucc38\ub41c \uac00\uc871","\ub9c8\uac00\ubcf5\uc74c 3\uc7a5","\uc608\uc218\ub2d8\uc740 \uc548\uc2dd\uc77c\uc5d0 \ubcd1\uc744 \uace0\uce58\uc2dc\uba70 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \ub9ce\uc740 \ubcd1\uc790\ub97c \uace0\uce58\uc2dc\uba70 \uad8c\uc704\ub97c \ub4dc\ub7ec\ub0b4\uc2dc\uace0 \uc5f4\ub450 \uc81c\uc790\ub97c \uc138\uc6b0\uc138\uc694. \uc885\uad50 \uc9c0\ub3c4\uc790\ub4e4\uc740 \uc608\uc218\ub2d8\uc744 \uc624\ud574\ud558\uace0 \ube44\ub09c\ud574\uc694. \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \ud589\ud558\ub294 \uc0ac\ub78c\uc774 \uc9c4\uc9dc \uac00\uc871\uc774\ub77c\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \uad00\uacc4\uc758 \uae30\uc900\uc774 \ud608\uc5f0\uc774 \uc544\ub2c8\ub77c \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\uc784\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uc911\uc2ec\uc73c\ub85c \uc0b4\uace0 \uc788\ub098\uc694?",B.a3D)
B.ac7=new A.U("\ub098\ub294 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ub9d0\uc500\uc744 \ub4e3\uace0 \uc788\ub098\uc694?","\uac19\uc740 \ub9d0\uc500\uc744 \ub4e4\uc5b4\ub3c4 \ubc18\uc751\uc740 \ub2e4\ub97c \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ub9d0\uc500\uc744 \ub4e3\uace0 \ubc14\ub85c \uc78a\uc5b4\ubc84\ub9ac\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub0b4 \uc0b6\uc5d0 \uc2e4\uc81c \ubcc0\ud654\uac00 \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.ae1=new A.U("\ub098\ub294 \ub9d0\uc500\uc744 \ub05d\uae4c\uc9c0 \ubd99\uc7a1\uace0 \uc788\ub098\uc694?","\ucc98\uc74c\uc5d0\ub294 \uc88b\uc558\uc9c0\ub9cc \uc2dc\uac04\uc774 \uc9c0\ub098\uba74\uc11c \uc2dd\uc5b4\uac00\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc5b4\ub824\uc6c0\uc774 \uc62c \ub54c \ud3ec\uae30\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uacc4\uc18d \ubd99\uc7a1\uace0 \uc788\ub098\uc694?")
B.abO=new A.U("\ub098\ub294 \ubbff\uc74c\uc744 \uc228\uae30\uc9c0 \uc54a\uace0 \ub4dc\ub7ec\ub0b4\uace0 \uc788\ub098\uc694?","\ubbff\uc74c\uc740 \uac10\ucd94\uae30 \uc704\ud55c \uac83\uc774 \uc544\ub2c8\uc5d0\uc694. \ub098\ub294 \uc8fc\ubcc0\uc5d0\uc11c \ub0b4 \ubbff\uc74c\uc744 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4dc\ub7ec\ub0b4\uace0 \uc788\ub098\uc694? \uc0b6\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uace0 \uc788\ub098\uc694?")
B.a38=s([B.ac7,B.ae1,B.abO],t.a)
B.XF=new A.b1("mark-lesson-4","path-mark","\ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ub9c8\uc74c","\ub9c8\uac00\ubcf5\uc74c 4\uc7a5","\uc608\uc218\ub2d8\uc740 \uc528 \ubfcc\ub9ac\ub294 \ube44\uc720\ub97c \ud1b5\ud574 \uc0ac\ub78c\uc758 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub530\ub77c \ub9d0\uc500\uc774 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \uc5b4\ub5a4 \ub9c8\uc74c\uc740 \ub9d0\uc500\uc744 \uae08\ubc29 \uc783\uc5b4\ubc84\ub9ac\uace0, \uc5b4\ub5a4 \ub9c8\uc74c\uc740 \uc5b4\ub824\uc6c0 \ub54c\ubb38\uc5d0 \ud3ec\uae30\ud574\uc694. \uadf8\ub7ec\ub098 \uc900\ube44\ub41c \ub9c8\uc74c\uc740 \ub9d0\uc500\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc5f4\ub9e4\ub97c \ub9fa\uc5b4\uc694. \ub610\ud55c \ub4f1\ubd88\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ub4dc\ub7ec\ub098\ub294 \ubbff\uc74c\uc758 \uc911\uc694\uc131\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ub9c8\uc74c\uc758 \uc0c1\ud0dc\uac00 \uc2e0\uc559\uc758 \uacb0\uacfc\ub97c \uacb0\uc815\ud55c\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ub9d0\uc500\uc744 \ub4e3\uace0 \uc788\ub098\uc694?",B.a38)
B.abp=new A.U("\ub098\ub294 \ub450\ub824\uc6c0\ubcf4\ub2e4 \ubbff\uc74c\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?","\uc0c1\ud669\uc774 \uc5b4\ub824\uc6b8\uc218\ub85d \ub450\ub824\uc6c0\uc774 \ucee4\uc9c8 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ubb38\uc81c\ub9cc \ubc14\ub77c\ubcf4\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \ud558\ub098\ub2d8\uc744 \ubc14\ub77c\ubcf4\uace0 \uc788\ub098\uc694?")
B.adm=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uaed8 \uc9c1\uc811 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?","\ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub9cc \uc758\uc9c0\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub098\ub294 \uc608\uc218\ub2d8\uaed8 \uc9c1\uc811 \uae30\ub3c4\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \ubb38\uc81c\ub97c \ub9e1\uae30\uace0 \uc788\ub098\uc694?")
B.abj=new A.U("\ub098\ub294 \ubbff\uc74c\uc744 \ud589\ub3d9\uc73c\ub85c \uc62e\uae30\uace0 \uc788\ub098\uc694?","\uc0dd\uac01\ub9cc\uc73c\ub85c\ub294 \ubcc0\ud654\uac00 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc544\uc694. \ub098\ub294 \uc2e4\uc81c\ub85c \ud589\ub3d9\ud558\uace0 \uc788\ub098\uc694? \ubbff\uc74c\uc774 \uc0b6\uc73c\ub85c \ub098\ud0c0\ub098\uace0 \uc788\ub098\uc694?")
B.a5b=s([B.abp,B.adm,B.abj],t.a)
B.Y_=new A.b1("mark-lesson-5","path-mark","\ubbff\uc74c\uc73c\ub85c \ub098\uc544\uac00\ub294 \uc0b6","\ub9c8\uac00\ubcf5\uc74c 5\uc7a5","\uc608\uc218\ub2d8\uc740 \uadc0\uc2e0 \ub4e4\ub9b0 \uc0ac\ub78c\uc744 \uc790\uc720\ub86d\uac8c \ud558\uc2dc\uace0, \ubcd1\ub4e0 \uc5ec\uc778\uc744 \uace0\uce58\uc2dc\uba70 \uc8fd\uc740 \uc18c\ub140\ub97c \uc0b4\ub9ac\uc138\uc694. \uac01\uac01\uc758 \uc0c1\ud669\uc5d0\uc11c \ubbff\uc74c\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud574\uc694. \uc0ac\ub78c\ub4e4\uc740 \ub450\ub824\uc6cc\ud588\uc9c0\ub9cc, \uc608\uc218\ub2d8\uc740 \ubbff\uc74c\uc744 \uac15\uc870\ud558\uc138\uc694. \ubbff\uc74c\uc740 \ub2e8\uc21c\ud55c \uc0dd\uac01\uc774 \uc544\ub2c8\ub77c \ud589\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uaed8 \ub098\uc544\uac00\ub294 \ubbff\uc74c\uc774 \uc0b6\uc744 \ubcc0\ud654\uc2dc\ud0a8\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ub450\ub824\uc6c0\ubcf4\ub2e4 \ubbff\uc74c\uc744 \uc120\ud0dd\ud558\uace0 \uc788\ub098\uc694?",B.a5b)
B.adL=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \ubbff\uace0 \uc788\ub098\uc694, \uc544\ub2c8\uba74 \uc758\uc2ec\ud558\uace0 \uc788\ub098\uc694?","\uc775\uc219\ud568 \ub54c\ubb38\uc5d0 \ubbff\uc74c\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \ub2f9\uc5f0\ud558\uac8c \uc5ec\uae30\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \uc9c4\uc9dc\ub85c \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.adA=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\ub9cc \uc758\uc9c0\ud558\uace0 \uc788\ub098\uc694?","\ub2e4\ub978 \uac83\ub4e4\uc5d0 \ub354 \uc758\uc9c0\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \ubbff\ub294 \uac83\uc774 \uc788\ub098\uc694? \ub098\ub294 \ubb34\uc5c7\uc744 \ubd99\uc7a1\uace0 \uc788\ub098\uc694?")
B.abB=new A.U("\ub098\ub294 \uc774\ud574\ub418\uc9c0 \uc54a\uc544\ub3c4 \uc21c\uc885\ud558\uace0 \uc788\ub098\uc694?","\ub2e4 \uc774\ud574\ud574\uc57c \uc6c0\uc9c1\uc774\ub824 \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc740 \uba3c\uc800 \uc21c\uc885\uc744 \uc6d0\ud558\uc138\uc694. \ub098\ub294 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\uace0 \uc788\ub098\uc694?")
B.a4n=s([B.adL,B.adA,B.abB],t.a)
B.XO=new A.b1("mark-lesson-6","path-mark","\ubd88\uc2e0\uacfc \uc21c\uc885\uc758 \ucc28\uc774","\ub9c8\uac00\ubcf5\uc74c 6\uc7a5","\uc608\uc218\ub2d8\uc740 \uace0\ud5a5\uc5d0\uc11c \ubbff\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub4e4\ub85c \uc778\ud574 \ub9ce\uc740 \uc77c\uc744 \ud558\uc9c0 \uc54a\uc73c\uc138\uc694. \uc81c\uc790\ub4e4\uc744 \ubcf4\ub0b4\uc2e4 \ub54c \uc544\ubb34\uac83\ub3c4 \uc758\uc9c0\ud558\uc9c0 \ub9d0\uace0 \ud558\ub098\ub2d8\ub9cc \uc758\uc9c0\ud558\ub77c\uace0 \ud558\uc138\uc694. \uc624\ubcd1\uc774\uc5b4 \uc0ac\uac74\uc744 \ud1b5\ud574 \ubd80\uc871\ud568 \uc18d\uc5d0\uc11c\ub3c4 \ud558\ub098\ub2d8\uc758 \ub2a5\ub825\uc774 \ub4dc\ub7ec\ub098\uc694. \ud558\uc9c0\ub9cc \uc81c\uc790\ub4e4\uc740 \uc5ec\uc804\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uace0 \uc788\uc5b4\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \ubd88\uc2e0\uc758 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc744 \ubbff\uace0 \uc788\ub098\uc694, \uc544\ub2c8\uba74 \uc758\uc2ec\ud558\uace0 \uc788\ub098\uc694?",B.a4n)
B.abl=new A.U("\ub098\ub294 \uac89\ubcf4\ub2e4 \ub9c8\uc74c\uc744 \ub354 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?","\uac89\uc73c\ub85c\ub294 \uad1c\ucc2e\uc544 \ubcf4\uc77c \uc218 \uc788\uc5b4\uc694. \ud558\uc9c0\ub9cc \ub0b4 \ub9c8\uc74c\uc740 \uc5b4\ub5a4 \uc0c1\ud0dc\uc778\uac00\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c\ub3c4 \uac19\uc740 \ubaa8\uc2b5\uc778\uac00\uc694?")
B.adQ=new A.U("\ub098\ub294 \ub0b4 \ub9c8\uc74c\uc744 \uc810\uac80\ud558\uace0 \uc788\ub098\uc694?","\ud589\ub3d9\ub9cc \uace0\uce58\ub824\uace0 \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ub0b4 \uc0dd\uac01\uacfc \ub9c8\uc74c\uc744 \ub3cc\uc544\ubcf4\uace0 \uc788\ub098\uc694? \uc9c0\uae08 \ub0b4 \uc548\uc5d0 \uc788\ub294 \uac10\uc815\uc740 \ubb34\uc5c7\uc778\uac00\uc694?")
B.adC=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc9c4\uc2ec\uc73c\ub85c \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?","\uc0c1\ud669\uc774 \uc544\ub2c8\ub77c \ud558\ub098\ub2d8\uc744 \ubbff\ub294 \uac83\uc774 \uc911\uc694\ud574\uc694. \ub098\ub294 \uacb0\uacfc\ub9cc \ubcf4\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \ubbff\uace0 \ub9e1\uae30\uace0 \uc788\ub098\uc694?")
B.a54=s([B.abl,B.adQ,B.adC],t.a)
B.WY=new A.b1("mark-lesson-7","path-mark","\ub9c8\uc74c\uc5d0\uc11c \uc2dc\uc791\ub418\ub294 \uc2e0\uc559","\ub9c8\uac00\ubcf5\uc74c 7\uc7a5","\uc608\uc218\ub2d8\uc740 \uc190 \uc53b\ub294 \uaddc\ub840\ub97c \ub450\uace0 \ud615\uc2dd\uc801\uc778 \uc2e0\uc559\uc744 \ucc45\ub9dd\ud558\uc138\uc694. \uc0ac\ub78c\uc744 \ub354\ub7fd\uac8c \ud558\ub294 \uac83\uc740 \uc678\uc801\uc778 \uac83\uc774 \uc544\ub2c8\ub77c \ub9c8\uc74c\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc774\ub77c\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub9d0\uacfc \ud589\ub3d9\uc758 \ubfcc\ub9ac\ub294 \ub9c8\uc74c\uc5d0 \uc788\uc5b4\uc694. \ub610\ud55c \uc774\ubc29 \uc5ec\uc778\uc758 \ubbff\uc74c\uc744 \ud1b5\ud574 \uc9c4\uc9dc \ubbff\uc74c\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubcf4\uc5ec\uc8fc\uc138\uc694. \uc774 \uc7a5\uc740 \uc2e0\uc559\uc758 \uc911\uc2ec\uc774 \uac89\uc774 \uc544\ub2c8\ub77c \ub9c8\uc74c\uc774\ub77c\ub294 \uac83\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \uac89\ubcf4\ub2e4 \ub9c8\uc74c\uc744 \ub354 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?",B.a54)
B.abo=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc788\ub098\uc694?","\uc54c\uace0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ubaa8\ub97c \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \uae4a\uc774 \uc54c\uace0 \uc788\ub098\uc694? \uc544\ub2c8\uba74 \ud53c\uc0c1\uc801\uc73c\ub85c\ub9cc \uc54c\uace0 \uc788\ub098\uc694?")
B.ach=new A.U("\ub098\ub294 \uc601\uc801\uc778 \ub208\uc73c\ub85c \ubcf4\uace0 \uc788\ub098\uc694?","\ub208\uc5d0 \ubcf4\uc774\ub294 \uac83\ub9cc \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc774 \ud558\uc2dc\ub294 \uc77c\uc744 \ubcf4\uace0 \uc788\ub098\uc694? \uc601\uc801\uc73c\ub85c \uae68\uc5b4 \uc788\ub098\uc694?")
B.acy=new A.U("\ub098\ub294 \uc2ed\uc790\uac00\ub97c \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?","\uace0\ub09c\uc744 \ud53c\ud558\ub824\uace0\ub9cc \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uc774 \uc6d0\ud558\uc2dc\ub294 \uae38\uc744 \uc774\ud574\ud558\ub824\uace0 \ud558\uace0 \uc788\ub098\uc694? \ub098\ub294 \uc5b4\ub5a4 \ud0dc\ub3c4\ub97c \uac00\uc9c0\uace0 \uc788\ub098\uc694?")
B.a6I=s([B.abo,B.ach,B.acy],t.a)
B.Xh=new A.b1("mark-lesson-8","path-mark","\uc601\uc801\uc778 \ub208\uacfc \ubbff\uc74c","\ub9c8\uac00\ubcf5\uc74c 8\uc7a5",'\uc608\uc218\ub2d8\uc740 \ub610 \ud55c \ubc88 \ub9ce\uc740 \uc0ac\ub78c\uc744 \uba39\uc774\uc2dc\uace0 \uc81c\uc790\ub4e4\uc5d0\uac8c \ubbff\uc74c\uc744 \uac00\ub974\uce58\uc138\uc694. \uadf8\ub7ec\ub098 \uc81c\uc790\ub4e4\uc740 \uc5ec\uc804\ud788 \uae68\ub2eb\uc9c0 \ubabb\ud558\uace0 \uc788\uc5b4\uc694. \uc608\uc218\ub2d8\uc740 "\ub108\ud76c\uac00 \uc544\uc9c1\ub3c4 \uae68\ub2eb\uc9c0 \ubabb\ud558\ub290\ub0d0"\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ubca0\ub4dc\ub85c\ub294 \uc608\uc218\ub2d8\uc744 \uadf8\ub9ac\uc2a4\ub3c4\ub85c \uace0\ubc31\ud558\uc9c0\ub9cc, \uc774\ud6c4 \uc2ed\uc790\uac00\ub97c \uc774\ud574\ud558\uc9c0 \ubabb\ud574\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uc774 \ub2e8\uc21c\ud55c \uc774\ud574\uac00 \uc544\ub2c8\ub77c \uae4a\uc740 \uae68\ub2ec\uc74c\uc774 \ud544\uc694\ud568\uc744 \ubcf4\uc5ec\uc918\uc694.',"\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc788\ub098\uc694?",B.a6I)
B.abv=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \ubbff\uace0 \uc788\ub098\uc694?","\ub9d0\ub85c\ub294 \ubbff\ub294\ub2e4\uace0 \ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub2e4\ub97c \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \uc9c4\uc9dc\ub85c \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694? \ub0b4 \uc120\ud0dd\uc5d0\uc11c \ub4dc\ub7ec\ub098\uace0 \uc788\ub098\uc694?")
B.ac2=new A.U("\ub098\ub294 \uacb8\uc190\ud55c \ud0dc\ub3c4\ub97c \uac00\uc9c0\uace0 \uc788\ub098\uc694?","\uc778\uc815\ubc1b\uace0 \uc2f6\uc5b4 \ud558\ub294 \ub9c8\uc74c\uc774 \ud06c\uc9c0 \uc54a\ub098\uc694? \ub098\ub294 \ub0ae\uc544\uc9c0\ub294 \uc120\ud0dd\uc744 \ud558\uace0 \uc788\ub098\uc694? \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc12c\uae30\uace0 \uc788\ub098\uc694?")
B.aed=new A.U("\ub098\ub294 \uae30\ub3c4\ub85c \ud558\ub098\ub2d8\uaed8 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?","\ub0b4 \ud798\uc73c\ub85c \ud574\uacb0\ud558\ub824\uace0\ub9cc \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uaed8 \uba3c\uc800 \ub098\uc544\uac00\uace0 \uc788\ub098\uc694? \uae30\ub3c4\ud558\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?")
B.a1R=s([B.abv,B.ac2,B.aed],t.a)
B.Xt=new A.b1("mark-lesson-9","path-mark","\ubbff\uc74c\uacfc \uacb8\uc190","\ub9c8\uac00\ubcf5\uc74c 9\uc7a5",'\uc608\uc218\ub2d8\uc740 \ubcc0\ud654\uc0b0\uc5d0\uc11c \uc601\uad11\uc744 \ubcf4\uc774\uc2dc\uace0 \uc81c\uc790\ub4e4\uc5d0\uac8c \ud558\ub098\ub2d8\uc758 \uc74c\uc131\uc744 \ub4e3\uac8c \ud558\uc138\uc694. \uc774\ud6c4 \uc81c\uc790\ub4e4\uc774 \uadc0\uc2e0\uc744 \ucad3\uc544\ub0b4\uc9c0 \ubabb\ud558\uc790 \ubbff\uc74c\uc758 \ubd80\uc871\uc744 \uc9c0\uc801\ud558\uc138\uc694. "\ubbff\ub294 \uc790\uc5d0\uac8c\ub294 \ub2a5\uce58 \ubabb\ud560 \uc77c\uc774 \uc5c6\ub2e4"\uace0 \ub9d0\uc500\ud558\uc138\uc694. \ub610\ud55c \ub204\uac00 \ud070 \uc790\uc778\uc9c0 \ub2e4\ud22c\ub294 \uc81c\uc790\ub4e4\uc5d0\uac8c \uc12c\uae40\uacfc \uacb8\uc190\uc744 \uac00\ub974\uce58\uc138\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \uacb8\uc190\uc774 \ud568\uaed8 \uac00\uc57c \ud568\uc744 \ubcf4\uc5ec\uc918\uc694.',"\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \ubbff\uace0 \uc788\ub098\uc694?",B.a1R)
B.acv=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \ubd99\uc7a1\uace0 \uc788\ub294 \uac83\uc774 \uc788\ub098\uc694?","\ud558\ub098\ub2d8\uc744 \ub530\ub974\uae30 \uc704\ud574 \ub0b4\ub824\ub193\uc544\uc57c \ud560 \uac83\uc774 \uc788\uc744 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ubb34\uc5c7\uc744 \ud3ec\uae30\ud558\uc9c0 \ubabb\ud558\uace0 \uc788\ub098\uc694? \uadf8\uac83\uc774 \ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \uc911\uc694\ud55c \uc790\ub9ac\uc5d0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694?")
B.adr=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc804\uc801\uc73c\ub85c \uc758\uc9c0\ud558\uace0 \uc788\ub098\uc694?","\ub0b4 \ud798\uc73c\ub85c \ud574\uacb0\ud558\ub824\uace0\ub9cc \ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub098\uc694? \ud558\ub098\ub2d8\uaed8 \ub9e1\uae30\uace0 \uc788\ub098\uc694? \ub098\ub294 \uc5b4\ub514\uae4c\uc9c0 \uc758\uc9c0\ud558\uace0 \uc788\ub098\uc694?")
B.acL=new A.U("\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub530\ub974\uae30 \uc704\ud574 \uacb0\ub2e8\ud558\uace0 \uc788\ub098\uc694?","\ub9c8\uc74c\uc73c\ub85c\ub9cc\uc774 \uc544\ub2c8\ub77c \ud589\ub3d9\uc774 \ud544\uc694\ud574\uc694. \ub098\ub294 \uc2e4\uc81c\ub85c \ub530\ub974\uace0 \uc788\ub098\uc694? \ubb34\uc5c7\uc774 \ub098\ub97c \uba48\ucd94\uac8c \ud558\uace0 \uc788\ub098\uc694?")
B.a2k=s([B.acv,B.adr,B.acL],t.a)
B.X4=new A.b1("mark-lesson-10","path-mark","\ud558\ub098\ub2d8 \ub098\ub77c\uc640 \uc81c\uc790\uc758 \uacb0\ub2e8","\ub9c8\uac00\ubcf5\uc74c 10\uc7a5","\uc608\uc218\ub2d8\uc740 \uacb0\ud63c\uacfc \uc774\ud63c\uc5d0 \ub300\ud574 \ub9d0\uc500\ud558\uc2dc\uba70 \ud558\ub098\ub2d8\uc758 \ub73b\uc744 \uac15\uc870\ud558\uc138\uc694. \uc5b4\ub9b0\uc544\uc774\uc640 \uac19\uc740 \uc790\uac00 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \ubc1b\ub294\ub2e4\uace0 \ud558\uc2dc\uba70 \uacb8\uc190\uc744 \uac00\ub974\uce58\uc138\uc694. \ubd80\uc790 \uccad\ub144\uc740 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc744 \ub4e3\uace0\ub3c4 \uc7ac\ubb3c\uc744 \ub0b4\ub824\ub193\uc9c0 \ubabb\ud574\uc694. \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8 \ub098\ub77c\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uac83\uc774 \uc27d\uc9c0 \uc54a\uc74c\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc774 \uc7a5\uc740 \ud558\ub098\ub2d8\uc744 \ub530\ub974\uae30 \uc704\ud55c \uacb0\ub2e8\uacfc \uc6b0\uc120\uc21c\uc704\ub97c \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\ubcf4\ub2e4 \ub354 \ubd99\uc7a1\uace0 \uc788\ub294 \uac83\uc774 \uc788\ub098\uc694?",B.a2k)
B.ac3=new A.U("\ub098\ub294 \uc5f4\ub9e4 \uc788\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?","\uac89\uc73c\ub85c\ub9cc \uc2e0\uc559\uc774 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc5b4\uc694. \ub0b4 \uc0b6\uc5d0 \uc2e4\uc81c \ubcc0\ud654\uc640 \uc5f4\ub9e4\uac00 \uc788\ub098\uc694? \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc9c4\uc9dc\uc778\uac00\uc694?")
B.acE=new A.U("\ub098\ub294 \ubbff\uc74c\uc73c\ub85c \uae30\ub3c4\ud558\uace0 \uc788\ub098\uc694?","\uae30\ub3c4\ub294 \uc2b5\uad00\uc774 \uc544\ub2c8\ub77c \ubbff\uc74c\uc774\uc5d0\uc694. \ub098\ub294 \uc815\ub9d0 \ubbff\uace0 \uae30\ub3c4\ud558\uace0 \uc788\ub098\uc694? \ud558\ub098\ub2d8\uc744 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.adV=new A.U("\ub098\ub294 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \uc815\uc9c1\ud55c \uc2e0\uc559\uc744 \uac00\uc9c0\uace0 \uc788\ub098\uc694?","\uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc774\uae30 \uc704\ud55c \uc2e0\uc559\uc774 \ub420 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c\ub3c4 \ub3d9\uc77c\ud55c \ubaa8\uc2b5\uc778\uac00\uc694? \uc9c4\uc9dc\uc778\uac00\uc694?")
B.a1f=s([B.ac3,B.acE,B.adV],t.a)
B.Y0=new A.b1("mark-lesson-11","path-mark","\ubbff\uc74c\uacfc \uc5f4\ub9e4","\ub9c8\uac00\ubcf5\uc74c 11\uc7a5","\uc608\uc218\ub2d8\uc740 \uc608\ub8e8\uc0b4\ub818\uc5d0 \uc785\uc131\ud558\uc2dc\uace0 \uc131\uc804\uc744 \uc815\uacb0\ud558\uac8c \ud558\uc138\uc694. \ubb34\ud654\uacfc\ub098\ubb34\ub97c \ud1b5\ud574 \uc5f4\ub9e4 \uc5c6\ub294 \uc2e0\uc559\uc744 \ucc45\ub9dd\ud558\uc138\uc694. \ub610\ud55c \ubbff\uc74c\uc73c\ub85c \uae30\ub3c4\ud560 \uac83\uc744 \uac00\ub974\uce58\uc138\uc694. \ud558\ub098\ub2d8\uc744 \ud5a5\ud55c \uc9c4\uc9dc \uc2e0\uc559\uc740 \uc5f4\ub9e4\ub85c \ub4dc\ub7ec\ub098\uc694. \uc774 \uc7a5\uc740 \ubbff\uc74c\uacfc \uc2e4\uc81c \uc0b6\uc758 \uc5f0\uacb0\uc744 \uac15\uc870\ud574\uc694.","\ub098\ub294 \uc5f4\ub9e4 \uc788\ub294 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?",B.a1f)
B.ade=new A.U("\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc9c4\uc2ec\uc73c\ub85c \uc0ac\ub791\ud558\uace0 \uc788\ub098\uc694?","\uc0ac\ub791\uc740 \ub9d0\uc774 \uc544\ub2c8\ub77c \uc6b0\uc120\uc21c\uc704\ub85c \ub4dc\ub7ec\ub098\uc694. \ub098\ub294 \ud558\ub098\ub2d8\uc744 \uac00\uc7a5 \uba3c\uc800 \ub450\uace0 \uc788\ub098\uc694? \ub0b4 \uc0b6\uc758 \uc120\ud0dd\uc740 \ubb34\uc5c7\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\ub098\uc694?")
B.abg=new A.U("\ub098\ub294 \uc774\uc6c3\uc744 \uc0ac\ub791\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?","\uac00\uae4c\uc6b4 \uc0ac\ub78c\uc77c\uc218\ub85d \uc0ac\ub791\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc5b4\uc694. \ub098\ub294 \uc5b4\ub5bb\uac8c \ub300\ud558\uace0 \uc788\ub098\uc694? \ud589\ub3d9\uc73c\ub85c \uc0ac\ub791\ud558\uace0 \uc788\ub098\uc694?")
